def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid_mask = remaining >= 0
    target_threshold = 0.1 * bins
    closeness = np.where(valid_mask, -np.abs(remaining - target_threshold), -np.inf)
    return np.where(valid_mask, closeness, -np.inf)

